import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Checkbox from "../../ui/checkbox";

// MODEL

export const Model = S.Struct({
  checkbox: Checkbox.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotCheckboxMessage = m("GotCheckboxMessage", {
  message: Checkbox.Message,
});

export const Message = S.Union([GotCheckboxMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [checkbox, checkboxCommands] = Checkbox.init({
    id: "checkbox-basic",
  });

  return [
    { checkbox },
    Command.mapMessages(checkboxCommands, (message) =>
      GotCheckboxMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotCheckboxMessage: ({ message }) => {
        const [checkbox, checkboxCommands] = Checkbox.update(
          model.checkbox,
          message
        );

        return [
          evo(model, { checkbox: () => checkbox }),
          Command.mapMessages(checkboxCommands, (message) =>
            GotCheckboxMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.checkbox.id,
        model: model.checkbox,
        view: Checkbox.view,
        viewInputs: {
          name: "terms",
          value: "accepted",
          toView: (attributes) =>
            h.div(
              [h.Class(Checkbox.checkboxRowClassName)],
              [
                h.button(
                  [
                    ...attributes.checkbox,
                    h.Class(Checkbox.checkboxControlClassName),
                  ],
                  model.checkbox.isChecked ? ["✓"] : []
                ),
                h.input(attributes.hiddenInput),
                h.div(
                  [h.Class(Checkbox.checkboxTextClassName)],
                  [
                    h.label(
                      [
                        ...attributes.label,
                        h.Class(Checkbox.checkboxLabelClassName),
                      ],
                      ["Accept terms and conditions"]
                    ),
                    h.p(
                      [
                        ...attributes.description,
                        h.Class(Checkbox.checkboxDescriptionClassName),
                      ],
                      ["You agree to the Terms of Service and Privacy Policy."]
                    ),
                  ]
                ),
              ]
            ),
        },
        toParentMessage: (message) => GotCheckboxMessage({ message }),
      }),
      h.p(
        [h.Class("text-sm text-gray-700")],
        [`Accepted: ${model.checkbox.isChecked ? "yes" : "no"}`]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as CheckboxBasicExample from "./main";

describe("Checkbox Basic example", () => {
  test("toggles accepted feedback", () => {
    Scene.scene(
      {
        update: CheckboxBasicExample.update,
        view: CheckboxBasicExample.view,
      },
      Scene.with(CheckboxBasicExample.init()[0]),
      Scene.expect(
        Scene.role("checkbox", { name: "Accept terms and conditions" })
      ).toExist(),
      Scene.expect(Scene.text("Accepted: no")).toExist(),
      Scene.click(
        Scene.role("checkbox", { name: "Accept terms and conditions" })
      ),
      Scene.expect(Scene.text("Accepted: yes")).toExist()
    );
  });
});
